import csv
from datetime import datetime
from collections import defaultdict

input_path = '/home/agent/workspace/bookstore_orders.csv'
output_path = '/home/agent/workspace/carrier-delivery-time.csv'

stats = defaultdict(lambda: {'count':0, 'total_hours':0.0})

def parse_dt(s):
    if not s:
        return None
    s = s.strip()
    for fmt in ('%Y-%m-%d %H:%M:%S', '%Y-%m-%d %H:%M', '%Y-%m-%d'):
        try:
            return datetime.strptime(s, fmt)
        except:
            continue
    return None

with open(input_path, newline='', encoding='utf-8') as f:
    reader = csv.DictReader(f)
    for row in reader:
        if row.get('fulfillment_status','').strip() != 'Delivered':
            continue
        carrier = row.get('carrier_name','').strip()
        if not carrier:
            continue
        order_ts = parse_dt(row.get('order_timestamp',''))
        actual_dt = parse_dt(row.get('actual_delivery_date',''))
        if not order_ts or not actual_dt:
            continue
        delta_hours = (actual_dt - order_ts).total_seconds() / 3600.0
        if delta_hours < 0:
            # skip negative? keep?
            continue
        stats[carrier]['count'] += 1
        stats[carrier]['total_hours'] += delta_hours

rows = []
for carrier, data in stats.items():
    count = data['count']
    avg = data['total_hours'] / count if count else 0
    rows.append({
        'CarrierName': carrier,
        'DeliveredOrders': count,
        'AvgDeliveryHours': round(avg, 2)
    })

rows.sort(key=lambda x: x['AvgDeliveryHours'])

with open(output_path, 'w', newline='', encoding='utf-8') as out:
    writer = csv.writer(out)
    writer.writerow(['CarrierName','DeliveredOrders','AvgDeliveryHours'])
    for r in rows:
        writer.writerow([r['CarrierName'], r['DeliveredOrders'], f"{r['AvgDeliveryHours']:.2f}"])

print('Done')

