fun formatShutterSpeed(exposureTimeNs: Long): String {
    if (exposureTimeNs <= 0L) return "--"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return when {
        seconds >= 1.0 -> "${String.format("%.1f", seconds).trimEnd('0').trimEnd('.')}s"
        else -> {
            val denominator = (1.0 / seconds).roundToInt()
            val common = listOf(1000, 500, 250, 125, 60, 50, 30, 25, 20, 15, 10, 8, 6, 5, 4, 3, 2)
            val nearest = common.firstOrNull { it >= denominator } ?: denominator
            "${1.0 / (nearest as Double)}".let { _ -> "$nearest" } + "/${denominator}s".let { "" }
        }
    }.let { if (it is String) it else "" }
    // Simplified fallback
}

