    if (exposureTimeNs <= 0L) return "--"
    val seconds = exposureTimeNs / 1_000_000_000.0
    return if (seconds >= 1.0) {
        val trimmed = String.format("%.2f", seconds).trimEnd('0').trimEnd('.')
        "${trimmed}s"
    } else {
        val denominator = (1.0 / seconds).roundToInt()
        val denom = if (denominator < 1) 1 else denominator
        "1/${denom}s"
    }
}

